export const getQuoteCenterOfferingsUrl = () => {
  return `${env.API_BASE_URL}/v1/center-services/quote`
}

/**
 * @summary Báo giá dịch vụ trung tâm cho BookingService hoặc khách hàng đặt lịch
 */
export const quoteCenterOfferings = async (
  serviceQuoteRequest: ServiceQuoteRequest,
  options?: RequestInit
): Promise<quoteCenterOfferingsResponseSuccess> => {
  const res = await fetch(getQuoteCenterOfferingsUrl(), {
    ...options,
    method: 'POST',
    headers: { 'Content-Type': 'application/json', ...options?.headers },
    body: JSON.stringify(serviceQuoteRequest)
  })

  const body = [204, 205, 304].includes(res.status) ? null : await res.text()
  if (!res.ok) {
    const err: globalThis.Error & { info?: quoteCenterOfferingsResponseError['data']; status?: number } =
      new globalThis.Error()
    const data: quoteCenterOfferingsResponseError['data'] = body ? JSON.parse(body) : {}
    err.info = data
    err.status = res.status
    throw err
  }
  const data: quoteCenterOfferingsResponseSuccess['data'] = body ? JSON.parse(body) : {}
  return { data, status: res.status, headers: res.headers } as quoteCenterOfferingsResponseSuccess
}

